solution = stone.Solution

# Create a new solution
result, sln_file = solution.CreateNewSolution(
'c:/your/solution', 'TestSolution', 'BaseProject'
)

if result.IsSuccessful:
print(sln_file)
else:
print(result.Errors[0].Description)

# Open the stone solution
stone.Solution.Open("C:\\Path\\To\\Solution\\Solution.stone")

# Sets Debug as the active solution configuration
for configuration in stone.Solution.SolutionConfigurations:
if configuration.Name == "Debug":
stone.Solution.SetActiveSolutionConfiguration(configuration)

# Open the stone solution
stone.Solution.Open("C:\\Path\\To\\Solution\\Solution.stone")

# Rename all "Main.st" files to "NewName.st"
for project in stone.Solution.Projects:
for file in project.Files:
if file.endswith("Main.st"):
project.RenameFile(file, "NewName.st", True)

# Save the solution
stone.Solution.Save()

import os

# Open the stone solution
stone.Solution.Open("C:\\Path\\To\\Solution\\Solution.stone")

# Update lib IAQ from version 1.0.0 to 2.0.0
for project in stone.Solution.Projects:
for subdir, dirs, libs in os.walk(project.GetOrCreateLibsFolder()):
for lib in libs:
if "IAQ_v.1.0.0" in lib:
project.RemoveFile(lib)
project.AddLibrary("C:\\Path\\To\\Lib\\IAQ_v.2.0.0.stlib")

stone.Solution.Save()

# Open the stone solution
stone.Solution.Open("C:\\Path\\To\\Solution\\Solution.stone")

# Search libs in all project
for project in stone.Solution.Projects:
for lib in project.GetLibsNames()
# ...

