stone.Solution.Open("C:\\Path\\To\\Solution\\Solution.stone")

# Loop through all folders contained in Sources\\ folder
for project in stone.Solution.Projects:
for folder in project.GetFolderRelativePaths():
if folder.startswith("Sources\\"):
# ...

