USING System;
USING System.UI;

VAR_GLOBAL CONSTANT
PAR1 : UDINT := 20;
PAR2 : UDINT := 21;
PAR3 : UDINT := 25;
PAR4 : UDINT := 30;
END_VAR

VAR_GLOBAL
bigData : ARRAY[0..1499] OF BYTE;
name : STRING := 'Device1';
password : STRING := 'Safe';
END_VAR

PROGRAM main
(*** Insert strategy here ***)
VAR
init : BOOL := TRUE;
i : INT;
tmpB : BYTE;
tmpW : WORD;
tmpDW : DWORD;
bigData2 : ARRAY[0..1499] OF BYTE;
name2 : STRING;
str : STRING;
END_VAR

IF init THEN
FOR i:= 0 TO 1499 BY 1 DO
bigData[i] := TO_BYTE(i MOD 50);
END_FOR;
init := FALSE;
END_IF;

(* Sets the BYTE setting with offset PAR1 *)
SetSettingB(PAR1, 25);

(* Gets the BYTE setting with offset PAR1 and write this in tmpB *)
GetSettingB(PAR1, tmpB);

(* Sets the WORD setting with offset PAR2 *)
SetSettingW(PAR2, 65000);

(* Gets the WORD setting with offset PAR2 and write this in tmpW *)
GetSettingW(PAR2, tmpW);

(* Sets the DWORD setting with offset PAR3 *)
SetSettingDW(PAR3, 3000000000);

(* Gets the DWORD setting with offset PAR3 and write this in tmpDW *)
GetSettingDW(PAR3, tmpDW);

(* Sets the settings with offset PAR4 *)
SetSetting(PAR4, bigData);

(* Gets the settings with offset PAR4 and write this in bigData2 *)
GetSetting(PAR4, bigData2);

(* Sets the current machine name *)
SetNameSetting(name);

(* Gets the current machine name *)
GetNameSetting(name2);

(* Sets the current Password settings *)
SetPasswordSetting(password);

(* Gets the current Password settings *)
GetPasswordSetting(str);

(* Refresh UI *)
SendVirtualKey(NO_KEY, 1);
END_PROGRAM

FUNCTION ManageKey : BOOL
VAR_INPUT
keyPressed, keyCounter : UINT;
END_VAR

IF keyPressed = KEY_ENTER THEN
(* Clears all settings from internal retained memory *)
ClearSettings();
