USING System;

VAR_GLOBAL
LogsBuffer : ARRAY [0..1024] OF BYTE;
END_VAR

PROGRAM Main
VAR
init : BOOL;
END_VAR
VAR_TEMP
error : INT;
END_VAR

IF init = FALSE THEN
init := TRUE;
error := InitLog(LogsBuffer);
IF error <> 0 THEN
//Manage log initialization error
END_IF;
END_IF;

WriteLog(LogLevel#Trace_Level, 'This is a TRACE log message');

WriteLog(LogLevel#Debug_Level, 'This is a DEBUG log message');

WriteLog(LogLevel#Info_Level, 'This is a INFO log message');

WriteLog(LogLevel#Warn_Level, 'This is a WARNING log message');

