VAR_GLOBAL RETAIN
my_retain:INT:=123;
initialized:BOOL:=FALSE;
END_VAR

VAR_GLOBAL
counter:UDINT;
retainMode:USINT;
retainInterval:UDINT;
retainMaxErase:UDINT;
retainMaxEraseErr:BOOL;
END_VAR

PROGRAM main
(*** Insert strategy there ***)
IF NOT initialized THEN
retainMode := 0;
retainInterval := 1000;
retainMaxErase := 3;
(* Sets the retain backup interval at 1s *)
RetainSetInterval(retainInterval);
(* Sets the retain backup mode 0 *)
RetainSetMode(retainMode);
(* Sets at 3 the number of erasures overflows limit *)
RetainSetMaxErasure(retainMaxErase);
initialized := TRUE;
END_IF;

(* Refresh UI *)
SendVirtualKey(NO_KEY, 1);
END_PROGRAM

FUNCTION ManageKey : BOOL
VAR_INPUT
keyPressed, keyCounter : UINT;
END_VAR

CASE keyPressed OF
KEY_ENTER:
(* Force a retain backup when the enter key is pressed *)
RetainForceBackup();
KEY_ESC:
(* Restore retain to default values when the esc key is pressed *)
RetainRestoreDefault();
END_CASE;

ManageKey := TRUE;
(*** Insert UI there ***)
END_FUNCTION

