USING System.UI;
USING System;
USING System.FileSystem.Enums;

{DEFINE USE_AYNC}
{IF def(USE_AYNC) }
USING System.FileSystem.Async;
{ELSE}
USING System.FileSystem;
{ENDIF}

PROGRAM main
{IF def(USE_AYNC) }
IF init=FALSE THEN
System.FileSystem.Async.FileSystemAsyncInit(m);
maskEvent:=CreateDynamicEvent();
GetTaskIdByTaskName('FS_TASK',taskId);
SubscribeEvent(taskId,maskEvent);
init:=TRUE;
END_IF;
{ENDIF}
(* Refresh UI *)
SendVirtualKey(NO_KEY, 1);
END_PROGRAM

VAR_GLOBAL
m:ARRAY [1..1024] OF BYTE;
init:BOOL;
status:INT;
file_id:DINT;
sRead:STRING;
sWrite:STRING:='Ciao';
FileName:STRING:='pippo.txt';
maskEvent:DWORD;
taskId:UINT;
END_VAR

PROGRAM FileSystemManager
END_PROGRAM

FUNCTION MyFileOpen:DINT
VAR_INPUT
s:STRING;
mode:FS_OpenMode;
END_VAR

{IF def(USE_AYNC) }
MyFileOpen:=FileOpen(PartitionType#PublicPartition,FileName,mode,maskEvent);
{ELSE}
MyFileOpen:=FileOpen(PartitionType#PublicPartition,FileName,FS_OpenMode#CREATE_RW);
{ENDIF}

END_FUNCTION

FUNCTION ManageKey : BOOL
VAR_INPUT
keyPressed, keyCounter : UINT;
END_VAR

(*** Insert UI here ***)

CASE status OF
0: file_id:=MyFileOpen(FileName,FS_OpenMode#CREATE_RW);
1: FileWrite(file_id,sWrite);
2: FileClose(file_id);
3: file_id:=MyFileOpen(FileName,FS_OpenMode#OPEN_READ);
4: FileRead(file_id,sRead);
5: FileClose(file_id);
END_CASE;

status:=(status+1) MOD 6;

DrawString('Hello FS',0,0);
ManageKey:=TRUE;
END_FUNCTION

