VAR_GLOBAL
m:ARRAY [1..1024] OF BYTE;
init:BOOL;
status:INT;
file_id:DINT;
sRead:STRING;
sWrite:STRING:='Ciao';
FileName:STRING:='pippo.txt';
maskEvent:DWORD;
taskId:UINT;
END_VAR

