(*
Example of use of Event I/O.
Add a digital event when digital input #3 changes.
Add an analog event when universal input #1 exceeeds 30.0 celsius degree from below.
*)

USING System;
USING System.IO;
CONFIGURATION Configuration1
RESOURCE Resource1 ON DEMOTARGET
TASK IOTask (EVENT:=DYNAMIC_EVENT);
PROGRAM IOInstance WITH IOTask : IOManager;
TASK MainTask (INTERVAL:=t#300ms, PRIORITY:=0);
PROGRAM MainInstance WITH MainTask : Main;
END_RESOURCE
END_CONFIGURATION

VAR_GLOBAL
init:BOOL;
mem:ARRAY [0..200] OF BYTE;
NO AT%QB31.0 : ARRAY[1..LIB_IO_MAX_NO_CH] OF BOOL;
ID AT%IB31.0 : ARRAY[1..LIB_IO_MAX_ID_CH] OF BOOL;
U1 AT%IB1.0 : uChannel;
uConfig1 AT%MB1.0 : uChannelConfig;
virtU AT%M61.0 : ARRAY[1..LIB_IO_MAX_U_CH] OF BOOL;
maskEvent:DWORD;
taskId:UINT;
END_VAR

PROGRAM IOManager
NO[3]:=NOT NO[3];
END_PROGRAM

PROGRAM main
IF init = FALSE THEN
uConfig1.mode_sel:=0;
uConfig1.mode_type:=0;
uConfig1.filter:=0;
init:=TRUE;
IO_OpenEventManager(mem);
maskEvent:=system.CreateDynamicEvent();
system.GetTaskIdByTaskName('IOTask',taskId);
System.SubscribeEvent(taskId,maskEvent);
IOAddDigitalEvent(3,FALSE,maskEvent);
IOAddAnalogEvent(1,30.0,0.5,1,maskEvent);
END_IF;
END_PROGRAM

