END_IF; {ENDREGION } {REGION CalcAlgorithm} //Calculate CRC of the first SerialBuffer&#39;s 8 bytes CRC := UDINT_TO_WORD(CalcAlgorithm(Algorithm#CRC, SerialBuffer, 0, 8)); SerialBuffer[8] := WORD_TO_BYTE(System.Math.SHR(CRC, 8)); SerialBuffer[9] := WORD_TO_BYTE(CRC); {ENDREGION } {REGION SerialWrite} //Write the first SerialBuffer&#39;s 15 bytes to the selected Serial Channel error := SerialWrite(SerialPort.Settings.Channel, SerialBuffer, 10); IF error = 15 THEN //Bytes written without errors //Clean serial port&#39;s receive buffer SerialPurge(SerialPort.Settings.Channel); ELSE //Manage Serial error END_IF; {ENDREGION } {REGION SerialClose} error := SerialClose(SerialPort.Settings.Channel); IF error &lt;&gt; LIB_SERIAL_OK THEN //Manage Serial error END_IF; {ENDREGION } END_PROGRAM GetModbusDebugID(USINT) System.Serial.GetModbusDebugID &ndash; Gets the Modbus Debug Ident currently used (ModbusShared or IDEOnly mode only).
