ION SerialWrite} //Write the first SerialBuffer&#39;s 15 bytes to the selected Serial Channel error := SerialWrite(SerialPort.Settings.Channel, SerialBuffer, 10); IF error = 15 THEN //Bytes written without errors //Clean serial port&#39;s receive buffer SerialPurge(SerialPort.Settings.Channel); ELSE //Manage Serial error END_IF; {ENDREGION } {REGION SerialClose} error := SerialClose(SerialPort.Settings.Channel); IF error &lt;&gt; LIB_SERIAL_OK THEN //Manage Serial error END_IF; {ENDREGION } END_PROGRAM IsSettingValid(System.Serial.SerialSettings, BOOL) System.Serial.IsSettingValid &ndash; Returns if serial settings are valid or not.
