examples.code:
USING System.UI;

PROGRAM MyUiProgram
VAR
uiMem : ARRAY[1..UI_MEM_SIZE] OF BYTE;
pLanMem : ARRAY[1..PLAN_MEM_SIZE] OF BYTE;
builtInMem : ARRAY[1..BUILT_IN_MEM_SIZE] OF BYTE;
init : BOOL;
END_VAR

// Setup of UI should be done once at application start-up.

IF init = FALSE THEN
init := TRUE;
SetupUI(uiMem, pLanMem, builtInMem);
END_IF;

// All UI operations must be executed in the same task that
// initializes the UI; otherwise operations are skipped.
DrawString('hello world', 0, 0);
END_PROGRAM

