items.description:
System.USB.UsbHostMode – Usb host mode

Members

Name
Description

NoneMode
USB host disabled

MsdMode
Mass Storage Device (MSD) mode: allows to transfer files to and from a USB pen drive.

Examples

(* This example shows how to implement the communication with a pen drive by setting
the proper mode and checking if the drive is ready. Furthermore it shows how to
write a file on the drive.
*)

USING System;
USING System.UI;
USING System.USB;
USING System.FileSystem;
USING System.Timer;

VAR_GLOBAL
info : System.SystemInfo;

mode : System.USB.UsbHostMode := UsbHostMode#NoneMode;
error : DINT(-20..9) := 0;
write_file : USINT := 0;
host_ready : BOOL;
dateTime : System.Timer.DateTime;
enableLabel : BOOL;
END_VAR

PROGRAM Main
VAR
current_mode : System.USB.UsbHostMode := UsbHostMode#NoneMode;
result : BOOL;
first_run : BOOL := TRUE;
partition : System.FileSystem.Enums.PartitionType := System.FileSystem.Enums.PartitionType#PenDrive;
filepath : STRING := 'test.txt';
openmode : System.FileSystem.Enums.FS_OpenMode := System.FileSystem.Enums.FS_OpenMode#OPEN_CREAT;
file_id : DINT;
written_bytes : DINT;
text : STRING := 'test';
END_VAR;

IF first_run THEN
first_run := FALSE;

(* Read the configured mode from the device *)
System.USB.GetUsbHostMode(mode);
END_IF;

host_ready := System.USB.IsUsbHostReady();

System.Timer.GetTime(dateTime);
IF dateTime.Second MOD 2 = 0 THEN
enableLabel := TRUE;
ELSE
enableLabel := FALSE;
END_IF;

(* The error, if present, must be manually removed from the UI *)
IF error = 0 THEN
IF current_mode <> mode THEN
current_mode := mode;
(* Set the current mode, according to the UI *)
result := System.USB.SetUsbHostMode(mode);
IF result = FALSE THEN
error := -1;
ELSE
error := 0;
END_IF;
END_IF;

(* Check for a push of the PRG key to save a file on the pen drive *)
IF mode = UsbHostMode#MsdMode THEN
IF write_file = 1 THEN
file_id := System.FileSystem.FileOpen(partition, filepath, openmode);
IF file_id >= 0 THEN
write_file := 2;
ELSE
write_file := 3;
error := file_id;
END_IF;
ELSIF write_file = 2 THEN
write_file := 3;
written_bytes := System.FileSystem.FileWrite(file_id, text);
IF written_bytes < 0 THEN
error := written_bytes;
ELSE
error := 0;
END_IF;
ELSIF write_file = 3 THEN
System.FileSystem.FileClose(file_id);
END_IF;
END_IF;
END_IF;

(* Refresh UI *)
SendVirtualKey(NO_KEY, 1);
END_PROGRAM

FUNCTION set_write_file
write_file := 1;
error := 0;
END_FUNCTION

