USING System;

PROGRAM Main
VAR
taskID : UINT;
eventID : DWORD;
customData : UDINT;
END_VAR
//Create dynamic event
eventID := CreateDynamicEvent();

//Get event driven task ID
taskID := GetTaskId(EventTask);

//Subscribe event on an event driven task
SubscribeEvent(taskID, eventID);

//Fire user event on EventTask task with a 10ms delay
SignalDynamicEvent(customData, 10, eventID);

//Unsubscribe dynamic event from event driven task EventTask
UnsubscribeEvent(taskID, eventID);

//Free dynamic event
FreeDynamicEvent(eventID);
END_PROGRAM

PROGRAM EventProgram
VAR_TEMP
event : Event;

eventsCount : INT;
error : INT;
END_VAR

//Get current event task pending events count
eventsCount := GetEventsCount();

IF eventsCount = 1 THEN
//Get current event
error := GetCurrentEvent(event);
//Manage event
ELSIF eventsCount > 1 THEN
//While there are pending events
WHILE GetEventsCount() > 0 DO
//Get first not managed event of the pending list
error := GetNextEvent(event);
IF error = DINT_TO_INT(ERR_OK) THEN
//Manage event
ELSE
//Manage event error
END_IF;
END_WHILE;
END_IF;

END_PROGRAM

CONFIGURATION Configuration1
RESOURCE Resource1 ON DEMOTARGET
TASK MainTask (INTERVAL:=t#300ms, PRIORITY:=3);
PROGRAM MainInstance WITH MainTask : Main;

TASK EventTask (EVENT:=DYNAMIC_EVENT);
PROGRAM EventInstance WITH EventTask : EventProgram;
END_RESOURCE
END_CONFIGURATION

