(* This example shows how to:
- set and get the mode of the MMC peripheral
- enable the MMC peripheral
- write a test file on it
*)
USING System.UI;
USING System.FileSystem;
USING System.FileSystem.Enums;
USING System.Timer;

VAR_GLOBAL
enable : BOOL := FALSE;
ready : DINT(-1..2) := -1;
mode : MmcModeType(MmcModeType#MMC_MODE_EXTERNAL_DRIVE..MmcModeType#MMC_MODE_PUBLIC_PARTITION) := MmcModeType#MMC_MODE_EXTERNAL_DRIVE;
error : DINT(-20..0) := System.FileSystem.ErrorCode.LIB_FS_OK;
write_file : USINT := 0;
END_VAR

PROGRAM Main
VAR
first_run : UINT := 1;
current_mode : MmcModeType;
current_enable : BOOL := FALSE;
partition : System.FileSystem.Enums.PartitionType := System.FileSystem.Enums.PartitionType#SdCard;
current_file_number : UINT := 0;
filepath : STRING[32];
openmode : System.FileSystem.Enums.FS_OpenMode := System.FileSystem.Enums.FS_OpenMode#OPEN_CREAT;
file_id : DINT;
written_bytes : DINT;
date_and_time : DATE_AND_TIME;
year, month, day, hour, minute, second, millisecond : UINT;
temp : STRING[5];
text : STRING;
END_VAR;

IF first_run = 1 THEN
(* During the first run the MMC mode is set to a default value (external drive) *)
first_run := 0;
System.FileSystem.Async.SetMicroSdMode(0, MmcModeType#MMC_MODE_EXTERNAL_DRIVE);
END_IF;

ready := System.FileSystem.Async.GetMicroSdStatus(0);
System.FileSystem.Async.GetMicroSdMode(0, current_mode);

IF enable <> current_enable THEN
(* When the 'enable' global variable is modified the state of the MMC is set
accordingly *)
error := System.FileSystem.Async.EnableMicroSd(0, enable);
IF error = System.FileSystem.ErrorCode.LIB_FS_OK THEN
current_enable := enable;
END_IF;
END_IF;

IF mode <> current_mode AND current_mode <> 0 THEN
(* When the 'mode' global variable is modified the mode of the MMC is set
accordingly *)
error := System.FileSystem.Async.SetMicroSdMode(0, mode);
IF error = System.FileSystem.ErrorCode.LIB_FS_OK THEN
current_mode := mode;
IF mode = MmcModeType#MMC_MODE_EXTERNAL_DRIVE THEN
partition := System.FileSystem.Enums.PartitionType#SdCard;
ELSIF mode = MmcModeType#MMC_MODE_PUBLIC_PARTITION THEN
partition := System.FileSystem.Enums.PartitionType#PublicPartition;
END_IF;
ELSE
mode := current_mode;
END_IF;
END_IF;

(* The following block of code is a simple state machine to manage the writing of a test
file on the MMC. *)
IF write_file = 1 THEN
(* The name of the test file contains a progressive number from 1 to 99 and the
current mode of the MMC. *)
current_file_number := current_file_number + 1;
IF current_file_number = 100 THEN
current_file_number := 0;
END_IF;

IF mode = MmcModeType#MMC_MODE_EXTERNAL_DRIVE THEN
filepath := System.Text.FORMAT('%02d-Ext_drive_test.txt', current_file_number);
ELSIF mode = MmcModeType#MMC_MODE_PUBLIC_PARTITION THEN
filepath := System.Text.FORMAT('%02d-Pub_part_test.txt', current_file_number);
END_IF;
(* The file is opened *)
file_id := System.FileSystem.FileOpen(partition, filepath, openmode);
IF file_id >= 0 THEN
write_file := 2;
ELSE
(* Error while opening the file *)
write_file := 3;
error := file_id;
END_IF;
ELSIF write_file = 2 THEN
write_file := 3;
(* The test file contains the current date and time. *)
System.Timer.GetTime(date_and_time);
SPLIT_DT(date_and_time, year, month, day, hour, minute, second, millisecond);
text := System.Text.FORMAT('%02d-', day);
temp := System.Text.FORMAT('%02d-', month);
text := System.Text.CONCAT(text, temp);
temp := System.Text.FORMAT('%d ', year);
text := System.Text.CONCAT(text, temp);
temp := System.Text.FORMAT('%02d:', hour);
text := System.Text.CONCAT(text, temp);
temp := System.Text.FORMAT('%02d:', minute);
text := System.Text.CONCAT(text, temp);
temp := System.Text.FORMAT('%02d', second);
text := System.Text.CONCAT(text, temp);
written_bytes := System.FileSystem.FileWrite(file_id, text);
IF written_bytes < 0 THEN
(* If something goes wrong the error is signaled *)
error := written_bytes;
ELSE
error := 0;
END_IF;
ELSIF write_file = 3 THEN
(* The file is closed *)
System.FileSystem.FileClose(file_id);
END_IF;

(* Refresh UI *)
SendVirtualKey(NO_KEY, 1);
END_PROGRAM

(* The following function triggers the writing of a test file on the MMC *)
FUNCTION set_write_file
IF write_file = 0 THEN
write_file := 1;
ELSE
write_file := 0;
END_IF;
error := 0;
END_FUNCTION

