USING System.Globalization;
VAR_GLOBAL

{ATTRIBUTE UOM FAHRENHEIT}
temp_F:REAL;
{ATTRIBUTE UOM CELSIUS}
temp_C:REAL:=32;
(* uom of value *)
temp_C_uom: UOM;

(* no UoM *)
height:REAL;
{ATTRIBUTE UOM FOOT}
height_FT:REAL:=10;
{ATTRIBUTE UOM METER}
height_MT:REAL;

(* a zone*)
z:ZONE:=SI;

(* temporary value*)
tmp:REAL;
tmp2:DINT;

END_VAR

PROGRAM main

(* direct conversion *)
CONVERT(temp_C,temp_F);

(* zone conversion, no matter final UoM *)
CONVERT_TO_ZONE(height_FT,height,z);

(* zone conversion, ignore destination UoM *)
CONVERT_TO_ZONE(height_FT,height_MT,z);

(* no conversion means identity conversion *)
CONVERT_TO_ZONE(height_FT,tmp2,NONE);

(*dual function*)
height_FT:=0;
CONVERT_FROM_ZONE(height,SI, height_FT);

(*Take UoM from a other variable*)
CONVERT_TO_ZONE(10.0, height_FT, tmp, z);
tmp:=0;
CONVERT_FROM_ZONE(30.0, z, tmp,height_FT);

(* uom saved in separate variable *)
temp_C_uom := UOM_OF(temp_C);
temp_C := 26;

CONVERT_UOM_ZONE(temp_C, temp_C_uom, temp_F, Imperial);
temp_C := 0;
CONVERT_ZONE_UOM(temp_F, Imperial, temp_C, temp_C_uom);

END_PROGRAM

