(*
Example of use of Event I/O.
Add a digital event when digital input #3 changes.
Add an analog event when universal input #1 exceeeds 30.0 celsius degree from below.
*)

USING System;
USING System.IO;
CONFIGURATION Configuration1
RESOURCE Resource1 ON DEMOTARGET
TASK IOTask (EVENT:=DYNAMIC_EVENT);
PROGRAM IOInstance WITH IOTask : IOManager;
TASK MainTask (INTERVAL:=t#300ms, PRIORITY:=0);
PROGRAM MainInstance WITH MainTask : Main;
END_RESOURCE
