USING System;
USING System.Math;
USING System.Net.TcpIp;
USING System.Text;
USING System.UI;

VAR_GLOBAL
req:ARRAY [0..1224] OF BYTE;
ipaddress: STRING := '10.10.10.30';
settings : TcpIpSettings;
buffer : ARRAY [0..1] OF BYTE;
memory : ARRAY [0..2048] OF BYTE;
stat : STRING := 'CLOSED';
conn : STRING := 'DISCONNECTED';
err : STRING := '';
isSessOpen : BOOL := FALSE;
res : DINT;
counter : INT := 0;
init : BOOL := TRUE;
msgid:UINT;
session: SINT;
clientId: USINT;
eventData:UDINT;
maskEvent:DWORD;
taskID:UINT;
END_VAR

PROGRAM main
(*** Insert strategy here ***)
(* Refresh UI *)
SendVirtualKey(NO_KEY, 1);
IF init THEN
settings.client := StrToIPAddr2(ipaddress);
settings.mode := TcpIp_Mode#Client;
settings.port := 10000;
settings.proto := TcpIp_Protocol#TCP;
init := FALSE;
END_IF;
END_PROGRAM

PROGRAM TcpIpManager
VAR
msgid:UINT;
session: SINT;
clientId: USINT;
eventData:Event;
END_VAR
GetCurrentEvent(eventData);
GetTcpEventInfo(eventData,msgid,session,clientId);
IF IsConnectionClosed(msgid) THEN
conn := 'DISCONNECTED';
ELSE
conn := 'CONNECTED';
END_IF;

END_PROGRAM

FUNCTION ManageKey : BOOL
VAR_INPUT
keyPressed, keyCounter : UINT;
END_VAR
ClearTexts();
CASE keyPressed OF
KEY_ALARM:
IF isSessOpen THEN
res := SessionClose(session);
IF res = 0 THEN
isSessOpen := FALSE;
stat := 'CLOSE';
ELSE
SessionClose(session);
err := CONCAT('ERROR: ', TO_STRING(res));
isSessOpen := TRUE;
END_IF;
ELSE
maskEvent:=CreateDynamicEvent();
GetTaskIdByTaskName('TcpTask',taskID);
SubscribeEvent(taskID,maskEvent);
settings.EventMask:=MaskEvent;
session := SessionOpen(settings, buffer, memory);
IF res = 0 THEN
isSessOpen := TRUE;
stat := 'OPEN';
ELSE
err := CONCAT('ERROR: ', TO_STRING(res));
END_IF;
END_IF;
KEY_ENTER:
counter := counter + 1;
buffer[0] := TO_BYTE(counter);
res := SessionWrite(session, clientId, buffer, 0, 2);
IF res >= 0 THEN
err := CONCAT('Sent: ',TO_STRING(TO_INT(buffer[0])));
ELSE
err := CONCAT('ERROR: ', TO_STRING(res));
END_IF;
END_CASE ;
(*** Insert UI here ***)
ManageKey:=TRUE;
DrawString(CONCAT('IP: ', ipaddress),0,0);
DrawString(CONCAT('Status: ', stat),1,0);
DrawString(CONCAT('Connection: ', conn),2,0);
DrawString(CONCAT('Output: ', TO_STRING(counter)), 4, 0);
DrawString(err, 7, 0);
END_FUNCTION

FUNCTION IPAddrToStr: STRING
VAR_INPUT
ip : UDINT;
END_VAR
VAR
adr : ARRAY [0..3] OF USINT;
i : INT;
END_VAR
adr[0]:=DWORD_TO_USINT(SHR(TO_DWORD(ip),24));
adr[1]:=DWORD_TO_USINT(SHR(TO_DWORD(ip),16));
adr[2]:=DWORD_TO_USINT(SHR(TO_DWORD(ip),8));
adr[3]:=DWORD_TO_USINT(SHR(TO_DWORD(ip),0));
FOR i := 3 TO 0 BY -1 DO
IPAddrToStr := CONCAT(IPAddrToStr, TO_STRING(adr[i]));
IF i <> 0 THEN
IPAddrToStr := CONCAT(IPAddrToStr, '.');
END_IF;
END_FOR;
END_FUNCTION

FUNCTION StrToIPAddr2: UDINT
VAR_INPUT
ip : STRING;
END_VAR
VAR
adr : ARRAY [0..3] OF USINT;
i : DINT;
j : INT := 3;
pCount : INT := 0;
END_VAR
FOR i := 0 TO LEN(ip) DO
IF ip[i]='.' THEN
adr[j] := TO_USINT(ip);
ip := RIGHT(ip, LEN(ip)-i-1);
pCount := pCount + 1;
j := j - 1;
i:=0;
IF pCount=3 THEN
EXIT;
END_IF;
END_IF;
END_FOR;
adr[j] := TO_USINT(ip);
StrToIPAddr2 := DWORD_TO_UDINT(SHL(TO_DWORD(adr[3]),24))+DWORD_TO_UDINT(SHL(TO_DWORD(adr[2]),16))+DWORD_TO_UDINT(SHL(TO_DWORD(adr[1]),8))+USINT_TO_UDINT(adr[0]);
END_FUNCTION

