+-----------------------------+| System.Serial.CalcAlgorithm || |System.Serial.Algorithm-| kind |ARRAY[*] OF BYTE-| buffer---------------buffer |-ARRAY[*] OF BYTEUDINT-| offset |UDINT-| count |+-----------------------------+Parameters Name Type Description kind System.Serial.Algorithm The type of algorithm. 0 = CRC, 1 = Checksum. buffer ARRAY[*] OF BYTE The buffer on which to calculate the algorithm. offset UDINT The starting offset. count UDINT The number of bytes. Examples USING System.Serial; VAR_GLOBAL Speed : UDINT := 19200; SerialPort : SerialPort := (Settings := (Speed := 19200, Channel := Serial_Channel#BMS2)); SerialBuffer : ARRAY [0..9] OF BYTE; END_VAR PROGRAM SerialProgram VAR_TEMP error : DINT; CRC : WORD; END_VAR {REGION IsSerialOpen - IsSettingValid - SerialOpen} //Check if Serial Port is opened, open it if not IF IsSerialOpen(SerialPort.Settings.Channel) = LIB_SERIAL_ERR_COM_CLOSED THEN //Serial Port is closed, check Settings before open it error := IsSettingValid(SerialPort.Settings, FALSE); IF error = LIB_SERIAL_OK THEN //Valid Settings, try to open Serial Port error := SerialOpen(SerialPort); IF error &lt;&gt; LIB_SERIAL_OK THEN //Manage Serial error RETURN; END_IF; ELSE //Manage Serial error RETURN; END_IF; END_IF; {ENDREGION } {REGION IsSettingValid - SerialChangeSettings} //Change Serial Port baudrate IF Speed &lt;&gt; SerialPort.Settings.Speed THEN error := IsSettingValid(SerialPort.Settings, FALSE); IF error = LIB_SERIAL_OK THEN //Valid Settings, try to change Serial Port Settings error := SerialChangeSettings(SerialPort.Settings); IF error &lt;&gt; LIB_SERIAL_OK THEN //Manage Serial error RETURN; END_IF; ELSE //Manage Serial error RETURN; END_IF; END_IF; {ENDREGION } {REGION SerialRead} //Read bytes from Serial Port and put them into SerialBuffer buffer error := SerialRead(SerialPort.Settings.Channel, SerialBuffer, 0); IF error = 0 THEN //No bytes read ELSIF error &gt; 0 THEN //error = number of bytes read ELSE //Manage Serial error END_IF; {ENDREGION } {REGION CalcAlgorithm} //Calculate CRC of the first SerialBuffer&#39;s 8 bytes CRC := UDINT_TO_WORD(CalcAlgorithm(Algorithm#CRC, SerialBuffer, 0, 8)); SerialBuffer[8] := WORD_TO_BYTE(System.Math.SHR(CRC, 8)); SerialBuffer[9] := WORD_TO_BYTE(CRC); {ENDREGION } {REGION SerialWrite} //Write the first SerialBuffer&#39;s 15 bytes to the selected Serial Channel error := SerialWrite(SerialPort.Settings.Channel, SerialBuffer, 10); IF error = 15 THEN //Bytes written without errors //Clean serial port&#39;s receive buffer SerialPurge(SerialPort.Settings.Channel); ELSE //Manage Serial error END_IF; {ENDREGION } {REGION SerialClose} error := SerialClose(SerialPort.Settings.Channel); IF error &lt;&gt; LIB_SERIAL_OK THEN //Manage Serial error END_IF; {ENDREGION } END_PROGRAM GetModbusDebugID(USINT) System.Serial.GetModbusDebugID &ndash; Gets the Modbus Debug Ident currently used (ModbusShared or IDEOnly mode only).
